          color: #222;
        }
        header {
          border-bottom: 2px solid #222;
          padding: 1rem 1.5rem;
          font-weight: 600;
          font-size: 1.5rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          user-select: none;
        }
        main {
          max-width: 720px;
          margin: 2rem auto;
          padding: 0 1rem;
        }
        .cards {
          display: flex;
          gap: 1rem;
          margin-bottom: 2rem;
          flex-wrap: wrap;
        }
        .card {
          background: white;
          border: 1.5px solid #222;
          border-radius: 6px;
          flex: 1 1 200px;
          padding: 1rem;
          display: flex;
          align-items: center;
          gap: 1rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          user-select: none;
        }
        .icon {
          flex-shrink: 0;
          color: #222;
          width: 32px;
          height: 32px;
        }
        .card-content {
          display: flex;
          flex-direction: column;
          gap: 0.25rem;
          font-size: 1rem;
        }
        .card-content .title {
          font-weight: 600;
        }
