          display: flex;
          gap: 0.5rem;
          align-items: center;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          user-select: none;
        }
        label {
          font-weight: 600;
          font-size: 1.1rem;
          flex-shrink: 0;
        }
        input[type="email"] {
          flex-grow: 1;
          font-size: 1rem;
          padding: 0.5rem 0.75rem;
          border: 1.5px solid #222;
          border-radius: 6px;
          font-family: 'Comic Sans MS', cursive, sans-serif;
          outline-offset: 2px;
        }
        input[type="email"]:focus {
          border-color: #555;
          outline: 2px solid #bbb;
        }
        button {
          background: white;
          border: 1.5px solid #222;
          border-radius: 9999px;
          padding: 0.5rem 1.25rem;
          font-family: 'Comic Sans MS', cursive, sans-serif;
