              <span>hi@acme.studio</span>
            </div>
          </article>
          <article className="card">
            <div className="icon" aria-hidden="true">{visitIcon}</div>
            <div className="card-content">
              <span className="title">Visit</span>
              <span>12 Park Lane</span>
            </div>
          </article>
        </section>

        <form onSubmit={handleSubscribe} noValidate aria-label="Newsletter subscription">
          <label htmlFor="email">Newsletter</label>
          <input
            id="email"
            type="email"
            placeholder="Your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            aria-describedby={error ? "email-error" : undefined}
            aria-invalid={error ? "true" : "false"}
          />
          <button type="submit">Join</button>
        </form>
        {error && (
          <p id="email-error" role="alert" className="error">
            {error}
          </p>
        )}
        {success && (
          <p role="alert" className="success">
            {success}
          </p>
        )}
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

